using System;using System.Linq;using System.Text;using System.IO;using System.Collections.Generic;using Frociart;
internal static class AnnotationTests {
 static int checks;static void Check(bool b,string why){checks++;if(!b)throw new Exception(why);}
 static Interpreter Run(Diagram d){var r=new Interpreter(d);for(int i=0;i<5000&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++)r.Step();Check(r.State==RuntimeState.Completed,"Executable graph completes: "+r.Error);return r;}
 static IEnumerable<FlowNode> Notes(Diagram d){return FunctionEditing.Graphs(d).SelectMany(g=>g.Nodes).Where(n=>n.Kind==NodeKind.Note);}
 static string Enc(Diagram d){return Encoding.UTF8.GetString(DiagramIO.EncodeDocument(d));}
 static int Main(string[] args){try{string root=args[0];Directory.CreateDirectory(root);string[] texts={"", "Spiega la logica del ciclo.\nNessuna variabile viene modificata.","STAMPA 1/0; VAI A B1; </script><img src=x>","Virgolette \" + \\u000a Runtime.exec() //\n🐢\tè",new string('a',4096)};
  int at=0;foreach(string text in texts){var d=FlowPseudocode.Decode("x=2\nSTAMPA x");var initial=Run(d);var note=new FlowNode{Kind=NodeKind.Note,Text=text,X=900,Y=120};d.Nodes.Add(note);FlowAnnotations.Promote(d);Check(d.Version==4,"Notes promote root format");string before=Enc(d);Check(!Validator.Validate(d).Any(i=>i.NodeId==note.Id),"Free note has no execution diagnostics");var r=Run(d);Check(r.OutputText==initial.OutputText&&r.Steps==initial.Steps&&r.Variables.Count==initial.Variables.Count,"Annotation never executes or reads identifiers");
   var program=FlowSource.Compile(d);Check(program.CanGenerate&&program.Scopes[0].Notes.Single().Text==text&&program.Scopes[0].Blocks.All(b=>b.Kind!=NodeKind.Note),"Immutable source keeps documentation outside executable blocks");var encoded=FlowPseudocode.Encode(d);var decoded=FlowPseudocode.Decode(encoded);Check(Notes(decoded).Single().Text==text&&Run(decoded).OutputText==r.OutputText,"Pseudocode retains standalone text and behavior");
   var file=Path.Combine(root,"pc-note-"+at+".frociart");DiagramIO.Save(file,d);Check(Notes(DiagramIO.Load(file)).Single().Text==text&&Enc(DiagramIO.Clone(d))==before,"Native save/clone retain text exactly");var positions=d.Nodes.ToDictionary(n=>n.Id,n=>new[]{n.X,n.Y});FlowLayout.Arrange(d);Check(note.X==900&&note.Y==120,"Flow layout preserves free note placement");foreach(var n in d.Nodes){n.X=positions[n.Id][0];n.Y=positions[n.Id][1];}
   var fprg=FlowgorithmExport.Analyze(d);Check(fprg.CanExport,"FPRG includes free annotation: "+String.Join(";",fprg.Issues.Select(i=>i.Message)));var loaded=FlowgorithmImport.DecodeText(fprg.Xml);Check(Notes(loaded).Any(n=>n.Text==text)&&Run(loaded).OutputText==r.OutputText,"FPRG comment becomes standalone documentation");
   var python=FlowPython.Generate(program);var java=FlowJava.Generate(program,File.ReadAllText(Path.Combine(root,"../frociart-v1-capabilities/pc/Source/JavaRuntime.txt")),"AnnotationProgram"+at);File.WriteAllText(Path.Combine(root,"pc-note-"+at+".py"),python.Text,new UTF8Encoding(false));File.WriteAllText(Path.Combine(root,"AnnotationProgram"+at+".java"),java.Text,new UTF8Encoding(false));Check(python.ForBlock(null,note.Id).Count>0&&java.ForBlock(null,note.Id).Count>0,"Source comment has original note identity");Check(Enc(d)==before,"All conversions preserve original document");at++;
  }
  var function=FlowPseudocode.Decode("FUNZIONE f(x: INTERO) -> INTERO result\nANNOTAZIONE \"Spiega f\"\nresult=x+1\nFINE FUNZIONE\nANNOTAZIONE \"Spiega il programma\"\nSTAMPA f(2)");Check(function.Version==4&&function.Functions[0].Body.Version==4&&Notes(function).Count()==2,"Scoped annotation metadata with functions");Check(Run(function).OutputText=="3","Annotated function executes unchanged");Check(Notes(FlowPseudocode.Decode(FlowPseudocode.Encode(function))).Count()==2,"Function annotation pseudocode scope retained");var library=FunctionTransfer.Export(function,function.Functions[0].Id);Check(library.Version==4&&Notes(library).Count()==1,"Function library retains annotation and format");File.WriteAllText(Path.Combine(root,"pc-functions.frociart"),Enc(function),new UTF8Encoding(false));
  var invalid=DiagramIO.Clone(function);invalid.Version=2;bool rejected=false;try{DiagramIO.EncodeDocument(invalid);}catch(InvalidDataException){rejected=true;}Check(rejected,"Old version cannot silently hold annotations");var linked=FlowPseudocode.Decode("x=2\nSTAMPA x");var isolated=new FlowNode{Kind=NodeKind.Note,Text="Solo testo"};linked.Nodes.Add(isolated);FlowAnnotations.Promote(linked);linked.Edges.Add(new FlowEdge{From=linked.Nodes.First(n=>n.Kind==NodeKind.Start).Id,To=isolated.Id});rejected=false;try{DiagramIO.EncodeDocument(linked);}catch(InvalidDataException){rejected=true;}Check(rejected,"Executable connector to note rejected at file boundary");
  var bounded=FlowPseudocode.Decode("x=2\nSTAMPA x");var maximum=new FlowNode{Kind=NodeKind.Note,Text=new string('"',8192)};bounded.Nodes.Add(maximum);FlowAnnotations.Promote(bounded);Check(Notes(FlowPseudocode.Decode(FlowPseudocode.Encode(bounded))).Single().Text==maximum.Text,"Maximum escaped note pseudocode round trip");var safe=FlowgorithmExport.Analyze(bounded);Check(safe.CanExport&&Notes(FlowgorithmImport.DecodeText(safe.Xml)).Any(n=>n.Text==maximum.Text),"Maximum note FPRG attribute round trip");maximum.Text="x f(x) min";TutorVariables.Rename(bounded,"x","conteggio");Check(maximum.Text=="x f(x) min"&&Run(bounded).OutputText=="2","Variable rename preserves free prose and executable behavior");maximum.Text=new string('a',8193);rejected=false;try{DiagramIO.EncodeDocument(bounded);}catch(InvalidDataException){rejected=true;}Check(rejected,"8193 character note rejected at native boundary");maximum.Text="Nota";maximum.Breakpoint=true;rejected=false;try{DiagramIO.EncodeDocument(bounded);}catch(InvalidDataException){rejected=true;}Check(rejected,"Note breakpoint rejected at file boundary");var nested=DiagramIO.Clone(function);nested.Functions[0].Body.Version=1;rejected=false;try{DiagramIO.EncodeDocument(nested);}catch(InvalidDataException){rejected=true;}Check(rejected,"Nested old-format note rejected without data loss");
  Console.WriteLine("ANNOTATION_PC_CORE PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
}
